from robot.api import logger
from prettytable import PrettyTable
from sys import version_info

import itertools

try:
    from BeautifulSoup import BeautifulSoup
except ImportError:
    from bs4 import BeautifulSoup


__all__ = ['table_counter_logger', 'simple_counter_logger']

SWITCHED_COLOR = itertools.cycle(['#ECEBFF', '#FFFFFF'])

COUNTERS_STYLE = """
<style type="text/css">
table.countersTable {
  background-color: #ECEBFF;
  text-align: left;
  border-collapse: collapse;
}
table.countersTable td, table.countersTable th {
  padding: 1px 10px;
}
table.countersTable tr.header {
  background: #A88AFF;
}
table.countersTable tr.header th {
  font-weight: bold;
  color: #FFFFFF;
}
</style>
        """


def table_counter_logger(counters_data):
    styled_table = COUNTERS_STYLE + _list_to_html_table(counters_data, classes='countersTable')
    logger.info(styled_table, html=True)
    return styled_table


def _list_to_html_table(counters_data, classes=None):
    data = _custom_column_order(counters_data)
    html_table = PrettyTable()
    html_table.field_names = ['counter name', 'counter id', 'actual value', 'expectations', 'verification result']
    html_table.header = True
    for row in data:
        html_table.add_row(row)
    _log_counters_to_console(html_table.get_string())
    html_ = html_table.get_html_string(**{'attributes': {'class': classes}} if classes else {})
    return _colorize_rows(html_)


def _custom_column_order(counters_data):
    return [
        [counter['name'], counter['counter_id'], counter['value'], counter['expectations'], counter['result']]
        for counter in counters_data
    ]


def _log_counters_to_console(data_frame):
    logger.console("^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^")
    logger.console(data_frame)


def _colorize_rows(html_):
    if version_info > (3, 0):
        soup = BeautifulSoup(html_, features='lxml')
    else:
        soup = BeautifulSoup(html_)
    rows = soup.findAll('tr')
    rows[0]['class'] = 'header'
    for row in rows[1:]:
        _set_row_color(row)
    return str(soup)


def _set_row_color(row):
    default_color = next(SWITCHED_COLOR)
    result = row.contents[-2]
    if 'False' in result:
        row['bgcolor'] = '#ffad99'
    elif 'True' in result:
        row['bgcolor'] = default_color
    else:
        row['bgcolor'] = 'ffffb3'


def simple_counter_logger(counters_data):
    logger.info('Counter verification results', also_console=True)
    for item in counters_data:
        logger.info(
            '{}\t\t{}\texpected value: {}\tactual value: {}\tverification result: {}'
            ''.format(item['name'], item['counter_id'], item['expectations'], item['value'], item['result']),
            also_console=True,
        )
